import assert from 'node:assert/strict';
import { mkdtemp, rm, stat, utimes, writeFile } from 'node:fs/promises';
import { createServer } from 'node:http';
import { join } from 'node:path';
import { loadConfig } from './history-only-reword-6qjyzwas/tree/mikro/dist/src/config.js';
import { parseCustomProviders } from './history-only-reword-6qjyzwas/tree/mikro/dist/src/custom-providers.js';
import { PiBackend } from './history-only-reword-6qjyzwas/tree/mikro/dist/src/mcp/backends/pi.js';
import { parseAgentSpec } from './history-only-reword-6qjyzwas/tree/mikro/dist/src/sdk/agent-spec.js';
const parent = '/home/genie/.local/share/mikro-engine-split/experiments-g8/final-local-smokes';
async function run(includeRead) {
  const root = await mkdtemp(join(parent, 'pi-post-final-'));
  let requests = 0;
  const tools = [{ name: 'emit_done', args: { answer: 'accepted' } }];
  if (includeRead) tools.push({ name: 'read', args: { path: 'post-final-canary.txt' } });
  const server = createServer(async (req, res) => {
    for await (const _chunk of req) { /* consume actual provider request */ }
    requests++;
    const delta = { role: 'assistant', tool_calls: tools.map((tool, index) => ({ index, id: `tool-${index}`, type: 'function', function: { name: tool.name, arguments: JSON.stringify(tool.args) } })) };
    res.writeHead(200, { 'Content-Type': 'text/event-stream' });
    res.end(`data: ${JSON.stringify({ id: 'local-post-final', choices: [{ index: 0, delta, finish_reason: 'tool_calls' }], usage: { prompt_tokens: 11, completion_tokens: 7, total_tokens: 18 } })}\n\ndata: [DONE]\n\n`);
  });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  process.env.PI_POSTFINAL_FIXTURE_KEY = 'local-fixture-only';
  try {
    const file = join(root, 'post-final-canary.txt');
    await writeFile(file, 'post-final read canary\n');
    const ancient = new Date('2000-01-01T00:00:00Z');
    await utimes(file, ancient, ancient);
    const before = (await stat(file)).atimeMs;
    const base = await loadConfig(root);
    const config = { ...base, system: 'Explicit local diagnostic', criteria: null, tools: [], validate: null, output: { schema: null }, budget: { maxCost: null, maxTokens: null, maxDepth: null }, gemini: { ...base.gemini, thinkingLevel: null }, model: { provider: 'postfinal-fixture', model: 'control', providers: parseCustomProviders({ 'postfinal-fixture': { 'base-url': `http://127.0.0.1:${server.address().port}/v1`, 'api-key-env': 'PI_POSTFINAL_FIXTURE_KEY', models: { control: { cost: { input: 1, output: 2 } } } } }, 'local post-final diagnostic') } };
    const progress = [];
    const agent = { name: 'fixture', toolName: 'mikro_fixture', dir: root, summary: 'fixture', spec: parseAgentSpec('engine: pi\nshape: loop\n', root) };
    const result = await new PiBackend().run(agent, { cwd: root, query: 'Return accepted final', context: null, config, maxRetries: 0 }, (message) => progress.push(message));
    const after = (await stat(file)).atimeMs;
    assert.equal(result.answer, 'accepted');
    assert.equal(requests, 1);
    return { includeRead, before, after, actualFileAccess: after > before, answer: result.answer, iterations: result.iterations, requests, progress, usage: result.usage };
  } finally {
    delete process.env.PI_POSTFINAL_FIXTURE_KEY;
    server.closeAllConnections();
    await new Promise((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
    await rm(root, { recursive: true, force: true });
  }
}
const finalOnly = await run(false);
const finalThenRead = await run(true);
assert.equal(finalOnly.actualFileAccess, false, 'control must rule out ambient/resource-loader file access');
console.log(JSON.stringify({ finalOnly, finalThenRead, externalModelCalls: 0, localProviderRequests: 2, jevCalls: 0 }));
assert.equal(finalThenRead.actualFileAccess, false, 'accepted final must deny subsequent filesystem work in the same actual SDK batch');

