import assert from 'node:assert/strict';
import { mkdtemp, rm } from 'node:fs/promises';
import { createServer } from 'node:http';
import { join } from 'node:path';
import { loadConfig } from './history-only-reword-6qjyzwas/tree/mikro/dist/src/config.js';
import { parseCustomProviders } from './history-only-reword-6qjyzwas/tree/mikro/dist/src/custom-providers.js';
import { LegacyMikroBackend } from './history-only-reword-6qjyzwas/tree/mikro/dist/src/mcp/backends/legacy.js';
import { runTurn, sessionResult } from './history-only-reword-6qjyzwas/tree/mikro/dist/src/mcp/server.js';
const parent = '/home/genie/.local/share/mikro-engine-split/experiments-g8/final-local-smokes';
async function run(childFinish) {
  const root = await mkdtemp(join(parent, 'child-ipc-failure-'));
  let requests = 0;
  const code = '```repl\nimport json\nchild = llm_query("child prompt")\nreceipt = json.dumps({"answer": child})\n```\nFINAL(receipt)';
  const server = createServer(async (request, response) => {
    for await (const _chunk of request) {}
    const index = requests++;
    if (index > 1) { response.writeHead(400); response.end('unexpected extra request'); return; }
    if (index === 1 && childFinish === 'error') { response.writeHead(400, { 'Content-Type': 'application/json' }); response.end(JSON.stringify({ error: { message: 'local child provider failed' } })); return; }
    response.writeHead(200, { 'Content-Type': 'text/event-stream' });
    response.end(`data: ${JSON.stringify({ id: `child-ipc-${index}`, object: 'chat.completion.chunk', model: 'control', choices: [{ index: 0, delta: { role: 'assistant', content: index === 0 ? code : 'child answer' }, finish_reason: index === 0 ? 'stop' : childFinish }], usage: { prompt_tokens: 11, completion_tokens: 7, total_tokens: 18 } })}\n\ndata: [DONE]\n\n`);
  });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  process.env.CHILD_IPC_FIXTURE_KEY = 'local-fixture-only';
  try {
    const base = await loadConfig(root);
    const schema = { type: 'object', properties: { answer: { type: 'string' } }, required: ['answer'], additionalProperties: false };
    const config = { ...base, system: null, criteria: null, tools: [], toolsLevel: 'core', validate: null, output: { schema }, budget: { maxCost: null, maxTokens: null, maxDepth: 0 }, cache: { ...base.cache, enabled: false }, storage: { ...base.storage, enabled: 'never' }, gemini: { ...base.gemini, thinkingLevel: null }, model: { provider: 'child-ipc-fixture', model: 'control', providers: parseCustomProviders({ 'child-ipc-fixture': { 'base-url': `http://127.0.0.1:${server.address().port}/v1`, 'api-key-env': 'CHILD_IPC_FIXTURE_KEY', models: { control: { cost: { input: 1, output: 2 } } } } }, 'local child IPC fixture') } };
    const outcome = await runTurn(new LegacyMikroBackend(), undefined, config, 'child-ipc-fixture', 'Return the child answer', 'sess_child_ipc', undefined, root, undefined, 1);
    const mcp = sessionResult(outcome.text, 'sess_child_ipc', outcome.failed);
    return { childFinish, requests, outcome, isError: mcp.isError === true, structuredContent: mcp.structuredContent };
  } finally {
    delete process.env.CHILD_IPC_FIXTURE_KEY;
    server.closeAllConnections();
    await new Promise((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
    await rm(root, { recursive: true, force: true });
  }
}
const control = await run('stop');
const length = await run('length');
const error = await run('error');
console.log(JSON.stringify({ control, length, error, externalModelCalls: 0, localProviderRequests: control.requests + length.requests + error.requests, jevCalls: 0 }));
assert.equal(control.isError, false, 'successful child control must remain successful');
assert.equal(control.requests, 2);
assert.equal(length.isError, true, 'failed child length completion must not become an ordinary successful Python FINAL/MCP answer');
assert.equal(error.isError, true, 'failed child error completion must not become an ordinary successful Python FINAL/MCP answer');
